"use client";

import { useEffect, useRef, useState } from "react";

// Optimised versions generated by scripts/optimize-media.sh (originals are kept unchanged).
// <name>-720.mp4 = H.264 720p/≤720px wide with faststart; <name>-poster.webp = first-frame poster.
const OPTIMIZED = new Set([
  "lowbannerfirst_optimized", "aboutbanner", "002bane_optimized",
  "dental-collage", "dental9", "dental10",
  "hairreels1", "hairreels2", "hairreels3", "hairreels4",
  "surgery1", "surgery2", "surgery3", "surgery4",
]);
// Full-width banners keep the original 1080p file on large screens (re-encoding gave no size benefit).
const LARGE_SCREEN_ORIGINAL = new Set(["lowbannerfirst_optimized", "aboutbanner"]);

function variants(src: string) {
  const name = src.split("/").pop()!.replace(/\.mp4$/, "");
  if (!OPTIMIZED.has(name)) return { small: src, large: src, poster: undefined as string | undefined };
  const small = `/media/video/${name}-720.mp4`;
  return { small, large: LARGE_SCREEN_ORIGINAL.has(name) ? src : small, poster: `/media/video/${name}-poster.webp` };
}

interface OptimizedVideoProps {
  src: string;
  className?: string;
  autoPlay?: boolean;
  loop?: boolean;
  muted?: boolean;
  playsInline?: boolean;
  controls?: boolean;
  poster?: string;
  /** Above-the-fold hero: attach and start immediately. Other videos load and play only when visible. */
  priority?: boolean;
}

export default function OptimizedVideo({
  src,
  className = "",
  autoPlay = false,
  loop = false,
  muted = true,
  playsInline = true,
  controls = false,
  poster,
  priority = false,
}: OptimizedVideoProps) {
  const ref = useRef<HTMLVideoElement>(null);
  const visible = useRef(false);
  const [activeSrc, setActiveSrc] = useState<string | null>(null);
  const v = variants(src);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.muted = muted; // set as a property so mobile autoplay policies see it
    const pick = () => (window.matchMedia("(min-width: 1024px)").matches ? v.large : v.small);

    if (priority) {
      visible.current = true;
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setActiveSrc(pick());
      return;
    }
    // Nothing is downloaded until the video approaches the viewport; it pauses when scrolled away.
    const io = new IntersectionObserver(
      ([entry]) => {
        visible.current = entry.isIntersecting;
        if (entry.isIntersecting) {
          setActiveSrc((current) => current ?? pick());
          if (autoPlay && el.currentSrc) el.play().catch(() => {});
        } else if (!el.paused) {
          el.pause();
        }
      },
      { rootMargin: "200px 0px", threshold: 0.01 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, [priority, autoPlay, muted, v.large, v.small]);

  // Start playback once a source has been attached (only if still on screen).
  useEffect(() => {
    const el = ref.current;
    if (el && activeSrc && autoPlay && visible.current) el.play().catch(() => {});
  }, [activeSrc, autoPlay]);

  return (
    <video
      ref={ref}
      className={className}
      src={activeSrc ?? undefined}
      poster={poster ?? v.poster}
      loop={loop}
      muted={muted}
      playsInline={playsInline}
      controls={controls}
      preload={priority ? "auto" : "none"}
      style={{ opacity: 1 }}
    >
      Your browser does not support the video tag.
    </video>
  );
}
